Fix an integer $k\ge3$, and write $$\ell_k(n)=\begin{cases}\log(en),&k=3,\\1,&k\ge4,\end{cases}
 \qquad U_k=\frac{\log2}{-\log(1-2^{-k})}.$$ There are constants $C_k,c_k>0$ such that $$\mathop{\mathrm{Var}}(H_n)\le C_kn\ell_k(n)\quad(n\ge k),\qquad
 \mathop{\mathrm{Var}}(H_n)\ge c_kn\quad\text{for all sufficiently large }n.$$ For every fixed $B>0$ there is $C_{k,B}<\infty$ such that $$\mathop{\mathrm{Var}}(T_{n,B})\le C_{k,B}n\ell_k(n)\quad(n\ge k).$$ If $B>U_k$, then also $\mathop{\mathrm{Var}}(T_{n,B})\ge c_kn$ for all sufficiently large $n$, with the size cutoff allowed to depend on $k$ and $B$.

For an integer $k\ge3$, put $$\beta=\frac{k}{k-1},\qquad
 K_k=\bigl(2^k(k-1)\bigr)^{k-1},\qquad
 C_k=4(2K_k)^{1/(k-1)}.$$ For every integer $u\ge k$, every $S\subseteq\{0,1\}^u$, and every integer $d\ge1$, $$\label{eq:lifetime-product}
 \tau_k(S)q_d(S)^\beta\le C_k d^\beta.$$ Consequently, for nonempty $S$ and $0<a\le q_d(S)$, $$\label{eq:lifetime-level}
 \tau_k(S)\le C_k d^\beta a^{-\beta}.$$ There is no upper restriction on $d$ and no positive lower cutoff on $a$.

For $i\le m<L$, on the event $\{|J_m|\ge1\}$, $$\label{eq:root-flip-tests}
 \mathbb P(A_m\mid\mathcal G_m)
 \le \mathbf1_{\{S_m\ne\varnothing\}}q_m^{|J_m|}.$$

Let $$W_m=\min\{L,\tau_k(S_m)+Z\}.$$ This is $\mathcal G_m$-measurable. For $i\le m<L$, on $A_m$, $$\label{eq:future-deletion-delay}
 \mathbb E\left[\sum_{\ell=m+1}^{L-1}\mathbf1_{A_\ell}
       \,\middle|\,\mathcal F_m^*\right]\le W_m.$$ Consequently $$\label{eq:conditional-weighted-delay}
 \mathbb E[D_i^2\mid\mathcal E]
 \le3\sum_{m=i}^{L-1}
        \mathbb E[\mathbf1_{A_m}W_m\mid\mathcal E].$$

There is a constant $C_k\ge1$, independent of the environment, such that for every $0<a\le1$, almost surely, $$\label{eq:conditional-occupation}
 \sum_{m=i}^{L-1}
 \mathbb P(S_m\ne\varnothing,\ q_m\ge a\mid\mathcal E)
 \le\min\{L,C_kd^\beta a^{-\beta}\}.$$

For $L\ge1$, almost surely and with a constant independent of the environment, $$\label{eq:integrated-occupation}
 \sum_{m=i}^{L-1}
 \mathbb E[\mathbf1_{\{S_m\ne\varnothing\}}q_m^\gamma\mid\mathcal E]
 \le
 \begin{cases}
 C_kd^\beta(1+\log L),&k=3,\\
 C_kd^\beta,&k\ge4.
 \end{cases}$$

For $L\ge1$, set $$h_k(L)=
 \begin{cases}
 1+\log L,&k=3,\\
 1,&k\ge4.
 \end{cases}$$ Then, almost surely, $$\label{eq:conditional-squared-delay}
 \mathbb E[D_i^2\mid\mathcal E]
 \le C_kd^{2\beta}h_k(L)\mathbf1_{\{V=0\}}
      +C_kLd^\beta\mathbf1_{\{V=1\}}
      +L^2\mathbf1_{\{V\ge2\}}.$$

Fix integers $k\ge3$ and $n\ge2k$, a real $B>0$, and a set of $k$ roots. Take $M$ independent uniform proper $k$-clauses on $n$ variables, where $M$ is a nonnegative integer with $M\le Bn$. Let $Z$ count clauses meeting a root, $V$ count clauses meeting at least two roots, and $d=\max\{1,Z\}$. For every fixed real $p\ge0$, $$\label{eq:incidence-moments}
 \mathbb Ed^p\le C_{k,B,p}.$$ For every fixed positive integer $r$, $$\label{eq:weighted-collision-moments}
 \mathbb E[d^p\mathbf1_{\{V\ge r\}}]\le C_{k,B,p,r}n^{-r}.$$

For $b\ge a$, put $R_{a,b}=V_b-X_a+1$ and $D_a=H_n-X_a$. Then $$\begin{aligned}
 R_{a,b}&=\sum_{m=a}^{b}\mathbf 1_{\{H_n>m\}},
 &0\le R_{a,b}&\le(b-a+1)\mathbf 1_{\{H_n>a\}},\label{eq:finite-cap-identity}\\
 D_a&=(H_n-a)_+.
 \label{eq:uncapped-identity}
\end{aligned}$$ For either $Z=R_{a,b}$ or $Z=D_a$, writing $\xi_{n,a}=2^nq_k^a$, $$\label{eq:cap-moments}
 \mathbb EZ\le 2^k\xi_{n,a},\qquad
 \mathbb EZ^2\le (2^{2k+1}-2^k)\xi_{n,a}.$$ If $X=V_b$ or $X=H_n$, respectively, then $$\begin{aligned}
 0\le\sqrt{\mathop{\mathrm{Var}}(X)}-\sqrt{\mathop{\mathrm{Var}}(X_a)}
 &\le 2^k\sqrt{1+q_k}\,\xi_{n,a}^{1/2},
 \label{eq:cap-sigma}\\
 0\le\mathop{\mathrm{Var}}(X)-\mathop{\mathrm{Var}}(X_a)
 &\le\bigl[2a\,2^k+2^{2k+1}-2^k\bigr]\xi_{n,a}.
 \label{eq:cap-variance}
\end{aligned}$$ The mean identities are $\mathbb EV_b=\mathbb EX_a-1+\mathbb ER_{a,b}$ and $\mathbb EH_n=\mathbb EX_a+\mathbb ED_a$.

For independent uniform proper clauses with fixed $k\ge3$, $$\label{eq:uncapped-variance}
 \mathop{\mathrm{Var}}(H_n)=
 \begin{cases}
 O(n\log n),&k=3,\\
 O_k(n),&k\ge4.
 \end{cases}$$ The same upper bounds hold for the uncapped last satisfiable index $H_n-1$ and, for every fixed $B>0$, for $\min\{H_n-1,\lfloor Bn\rfloor\}$. Write $s_k(n)=\sqrt{n\ell_k(n)}$, with $\ell_k$ as in the introduction. For each of these statistics, or for $T_{n,B}$ from Theorem <a href="#thm:variance" data-reference-type="ref" data-reference="thm:variance">1</a>, there is a constant $C$ (depending on fixed $k$ and, when present, $B$) such that $$\label{eq:mean-centered-concentration}
 \mathbb P\bigl(|X-\mathbb EX|\ge t s_k(n)\bigr)\le C t^{-2}
 \qquad(t>0)$$ for all sufficiently large $n$.

Partition $N=n_1+n_2$ variables into blocks of sizes $n_1,n_2\ge k$, and put $w_j=n_j/N$ and $n=\min\{n_1,n_2\}$. Fix an integer $M\ge0$ and $0<\varepsilon<1$. Each of $M$ independent local trials chooses block $j$ with probability $w_j$ and inserts an independent uniform proper $k$-clause in that block. Each of $M$ independent diluted global trials inserts an independent uniform proper $k$-clause on all $N$ variables with probability $1-\varepsilon$, and inserts no clause otherwise. Let $Q_{\mathrm{loc}}$ and $Q_{\mathrm{dil}}$ be the respective probabilities that the resulting formulas are satisfiable. Then $$\begin{aligned}
 Q_{\mathrm{dil}}
 &\ge Q_{\mathrm{loc}}-
 C_k M\varepsilon^{-k}\sum_{j=1}^{2}\frac{w_j}{n_j^k},
 & C_k&=\frac{[k(k-1)]^k}{2^k},\label{cmp:weighted-replacement}\\
 Q_{\mathrm{dil}}
 &\ge Q_{\mathrm{loc}}-\frac{C_kM}{\varepsilon^k n^k}.
 \label{cmp:coarse-replacement}
\end{aligned}$$ For $N=n+1$, if all local trials instead use a fixed main set of $n\ge k$ variables, then $$\label{cmp:neighbor-replacement}
 Q_{\mathrm{dil}}\ge Q_{\mathrm{loc}}
       -\frac{D_kM}{\varepsilon^k n^k},\qquad
 D_k=\frac{k^{2k}}{2^k}.$$ These statements impose no restriction on a block-size ratio.

For every integer $u\ge3$, every $S\subseteq\{0,1\}^u$, and every integer $g\ge1$, if the $g$ triples are independent uniform proper three-clauses on these $u$ variables, then $$\label{eq:prefix-one-pair}
 \mathbb P(\text{the \(g\) triples kill \(S\)})
 \ge q_1(S)-64(g^{-2}+u^{-2}).$$

Let $K=64$. There is an absolute constant $K_1$ such that for every integer $u\ge3$, every nonempty $S\subseteq\{0,1\}^u$, every integer $d\ge1$, and every $a$ with $4Kd/u^2\le a\le1$, $$\label{eq:prefix-lifetime}
 q_d(S)\ge a\quad\Longrightarrow\quad
 \tau(S)\le K_1d^{3/2}a^{-3/2}.$$

Set $\mathcal W_m=\min\{L,\tau(S_m)/p_0\}$. For $i\le m<L$, on $A_m$, $$\mathbb E\left[\sum_{\ell=m+1}^{L-1}\mathbf 1_{\{A_\ell\}}
                  \,\middle|\,\mathcal F_m\right]\le\mathcal W_m.$$ Consequently, $$\label{eq:prefix-weighted-delay}
 \mathbb ED_i^2\le3\sum_{m=i}^{L-1}\mathbb E[\mathbf 1_{\{A_m\}}\mathcal W_m].$$

For every $i\le m<L$, on the $\mathcal G_m$-measurable event $\{\max_{j\in R}s_{j,m}\le d,\ |J_m|\ge1\}$, $$\label{eq:prefix-root-tests}
 \mathbb P(A_m\mid\mathcal G_m)
 \le\mathbf 1_{\{S_m\ne\varnothing\}}q_m^{|J_m|}.$$

For all sufficiently large $n$, uniformly in $i$ and in the value of $C_i$, $$\label{eq:prefix-reduction}
 \mathbb ED_i^2\le C(1+d^{3/2})+
 C d^{3/2}\sum_{m=i}^{L-1}
       \mathbb E\bigl[\mathbf 1_{\{S_m\ne\varnothing\}}q_m^{3/2}\bigr].$$

For all sufficiently large $n$ and every $a_0\le a\le1$, $$\label{eq:prefix-occupation}
 \sum_{m=i}^{L-1}\mathbb P(S_m\ne\varnothing,\ q_m\ge a)
 \le Cd^{3/2}a^{-3/2}.$$ For $0<a<a_0$, the same sum is at most $L$.
